#!/usr/bin/env node
// Vendor gate for the oswe plugin — zero runtime deps, Node >= 20, imports nothing from skills/.
// Verifies skills/audit/vendor/tree-sitter/ (the committed web-tree-sitter loader + WASM grammars
// generated by skills/audit/scripts/build-grammars.mjs) against its MANIFEST.json:
//   1. every manifest entry has a file whose sha256 matches (missing / mismatching -> violation);
//   2. no file exists in the directory that the manifest does not list (extra -> violation);
//      MANIFEST.json and LICENSES.md are the only unlisted files allowed;
//   3. the directory's total size stays within MAX_BYTES.
// Run from the repo root:  node .github/scripts/check-vendor.mjs
// Exit 0 = all good; exit 1 = a violation (printed); exit 2 = the gate itself failed to run.
import { readFileSync, readdirSync, statSync, existsSync } from "node:fs";
import { join, dirname, relative, sep } from "node:path";
import { fileURLToPath } from "node:url";
import { createHash } from "node:crypto";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
const VENDOR = join(ROOT, "skills", "audit", "vendor", "tree-sitter");
const UNHASHED = new Set(["MANIFEST.json", "LICENSES.md"]);
// Measured on the committed bytes: the seven grammars are ~11 MB raw but are committed gzipped (~1 MB).
const MAX_BYTES = 10 * 1024 * 1024;

const errors = [];
const ok = (m) => console.log(`  ok  ${m}`);
const bad = (m) => { errors.push(m); console.log(`  XX  ${m}`); };

const walk = (dir) => {
  const out = [];
  for (const e of readdirSync(dir)) {
    const p = join(dir, e);
    if (statSync(p).isDirectory()) out.push(...walk(p));
    else out.push(p);
  }
  return out;
};

try {
  if (!existsSync(VENDOR)) throw new Error(`vendor directory not found: ${VENDOR}`);
  const manifest = JSON.parse(readFileSync(join(VENDOR, "MANIFEST.json"), "utf8"));

  // Relative posix-style names of everything on disk, with sizes.
  const onDisk = new Map(walk(VENDOR).map((p) => [relative(VENDOR, p).split(sep).join("/"), statSync(p).size]));

  console.log("1) manifest entries: present and sha256-identical");
  for (const [file, meta] of Object.entries(manifest)) {
    if (!onDisk.has(file)) { bad(`${file}: listed in MANIFEST.json but missing`); continue; }
    const actual = createHash("sha256").update(readFileSync(join(VENDOR, file))).digest("hex");
    actual === meta.sha256 ? ok(`${file} (${meta.package} ${meta.version})`) : bad(`${file}: sha256 mismatch (manifest ${meta.sha256}, actual ${actual})`);
  }

  console.log("2) no unlisted files");
  const extras = [...onDisk.keys()].filter((f) => !(f in manifest) && !UNHASHED.has(f));
  for (const f of extras) bad(`${f}: present but not listed in MANIFEST.json`);
  if (!extras.length) ok("every file is listed (besides MANIFEST.json / LICENSES.md)");
  for (const f of UNHASHED) onDisk.has(f) ? ok(`${f} present`) : bad(`${f}: missing`);

  console.log("3) size budget");
  const total = [...onDisk.values()].reduce((a, b) => a + b, 0);
  const summary = `${total} bytes (${(total / 1048576).toFixed(2)} MiB) of ${MAX_BYTES} allowed`;
  total <= MAX_BYTES ? ok(`vendor dir is ${summary}`) : bad(`vendor dir is ${summary} — over budget`);
} catch (e) {
  console.error(`check-vendor could not run: ${e.message}`);
  process.exit(2);
}

console.log("");
if (errors.length) {
  console.error(`FAIL: ${errors.length} vendor violation(s).`);
  process.exit(1);
}
console.log("PASS: vendored tree-sitter matches MANIFEST.json and is within budget.");
